local Players=game:GetService("Players")local TweenService=game:GetService("TweenService")local RunService=game:GetService("RunService")local LocalPlayer=Players.LocalPlayer local Character=LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()local Humanoid=Character:WaitForChild("Humanoid")local RootPart=Character:WaitForChild("HumanoidRootPart")local IsRunning=true local CollectedTargets={}local StartCFrame=RootPart.CFrame local IsReturning=false local CurrentTarget=nil local function GetAllTargets()local targets={}for _,obj in ipairs(workspace:GetDescendants())do if obj:IsA("Model")and(obj.Name:lower():find("honey")or obj.Name:lower():find("jar")or obj.Name:lower():find("candy"))then if not table.find(CollectedTargets,obj)then table.insert(targets,obj)end end end return targets end local function MoveToTarget(target)if not target or not IsRunning or IsReturning then return end CurrentTarget=target local targetPos=target:GetPivot().Position local distance=(RootPart.Position-targetPos).Magnitude while distance>5 and IsRunning and not IsReturning do targetPos=target:GetPivot().Position distance=(RootPart.Position-targetPos).Magnitude if distance>5 then local tween=TweenService:Create(RootPart,TweenInfo.new(distance/20,Enum.EasingStyle.Linear,Enum.EasingDirection.Out),{CFrame=CFrame.new(targetPos)})tween:Play()tween.Completed:Wait()end task.wait(0.1)end if distance<=5 and IsRunning then table.insert(CollectedTargets,target)CurrentTarget=nil end end local function ReturnToStart()IsReturning=true local distance=(RootPart.Position-StartCFrame.Position).Magnitude while distance>5 and IsRunning do distance=(RootPart.Position-StartCFrame.Position).Magnitude if distance>5 then local tween=TweenService:Create(RootPart,TweenInfo.new(distance/20,Enum.EasingStyle.Linear,Enum.EasingDirection.Out),{CFrame=StartCFrame})tween:Play()tween.Completed:Wait()end task.wait(0.1)end IsReturning=false end LocalPlayer.CharacterAdded:Connect(function(newChar)Character=newChar Humanoid=Character:WaitForChild("Humanoid")RootPart=Character:WaitForChild("HumanoidRootPart")CollectedTargets={}StartCFrame=RootPart.CFrame CurrentTarget=nil end)task.spawn(function()while IsRunning do if not Character or not Character.Parent then Character=LocalPlayer.CharacterAdded:Wait()Humanoid=Character:WaitForChild("Humanoid")RootPart=Character:WaitForChild("HumanoidRootPart")StartCFrame=RootPart.CFrame end if not CurrentTarget then local targets=GetAllTargets()if #targets>0 then for _,target in ipairs(targets)do if IsRunning and not IsReturning then MoveToTarget(target)task.wait(0.1)end end else if not IsReturning then ReturnToStart()end task.wait(1)end end task.wait(0.1)end end)task.spawn(function()while IsRunning do task.wait(7200)CollectedTargets={}end end)_G.Stop=function()IsRunning=false end
